<?php use Hls\Http\View as V; ?>
<?php if($error): ?><div class="alert alert-error"><?= V::escape($error) ?></div><?php endif ?>
<?php if($access->can('finance.category.manage')): ?><section class="panel"><h2>Tambah Kategori</h2><form method="post" class="form-grid"><?= $this->csrf() ?><input type="hidden" name="action" value="save"><label>Kode<input name="code" maxlength="40" required></label><label>Nama<input name="name" maxlength="160" required></label><label>Status<select name="active"><option value="1">Aktif</option><option value="0">Nonaktif</option></select></label><button class="button button-primary" type="submit">Simpan</button></form></section><?php endif ?>
<section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= V::escape($row['code']) ?></td><td><?= V::escape($row['name']) ?></td><td><?= $row['active']?'Aktif':'Nonaktif' ?></td></tr><?php endforeach ?></tbody></table><?php if(!$rows): ?><p class="empty-state">Belum ada kategori pengeluaran.</p><?php endif ?></div></section>
